 readonly Dictionary<string,DateTimeOffset> archiveRetry=new();
 async Task ArchiveSavedResults(){foreach(var entry in History.SelectMany(j=>j.Targets.Select(t=>(Job:j,Target:t))).Where(x=>x.Target.State!=null&&(x.Target.Status is "Completed" or "CompletedWithErrors" or "Failed" or "Cancelled" or "VerifiedAfterReboot")&&x.Target.State.DiagnosticStatus is not ("Pending" or "Running" or "LegacyRunning")&&x.Target.State.RestoreStatus is not ("Pending" or "InterventionRequired")).Where(x=>!archivedJobs.Contains(x.Job.Id+x.Target.Host)&&(!archiveRetry.TryGetValue(x.Job.Id+x.Target.Host,out var next)||next<DateTimeOffset.UtcNow)).Take(2).ToList()){if(closing)return;var key=entry.Job.Id+entry.Target.Host;archiveRetry[key]=DateTimeOffset.UtcNow.AddMinutes(5);try{await remote.Logs(entry.Target,entry.Job.Id,true);archivedJobs.Add(key);Store.Write("archived-jobs.json",archivedJobs.ToList());}catch{}}}
