 static string CommandOutput(string output,bool wsus)=>LogPresentation.LocalTimes(LogPresentation.Compact(wsus?output:Regex.Replace(output,@"(?m)^Отчёт WSUS:[^\r\n]*(?:\r?\n|$)","")));
 string ChannelOutput(ComputerRow row,bool wsus){var r=ExecutionRow(row,wsus);var stored=r.Target.Output;if(r.Target.State!=null&&!stored.StartsWith("## ")&&stored.Contains("--- runner.log ---")){var legacy=new PollResult{State=r.Target.State,Output=stored};foreach(Match match in Regex.Matches(stored,@"(?ms)^--- [^\r\n]*updates\.json ---\r?\n(.*?)(?=^--- |\z)")){try{legacy.Updates.AddRange(JsonSerializer.Deserialize<List<UpdateOutcome>>(match.Groups[1].Value.Trim(),Store.Options)??new());}catch{}}stored=PresentResult(r.Host,legacy);}var output=!string.IsNullOrWhiteSpace(stored)?CommandOutput(stored,wsus):r.JobId==""?(wsus?"Для этого компьютера пока нет сохранённых заданий WSUS.":"Для этого компьютера пока нет результатов команд."):"Задание: "+r.JobId+"\nСостояние: "+r.Status+"\nОжидание результата…";return output+(servicingReports.TryGetValue(r.JobId+row.Host,out var diagnostic)?"\n\n"+diagnostic:"");}
 void ShowCurrent(){if(ComputerGrid.SelectedItem is ComputerRow r){OutputBox.Text=ChannelOutput(r,false);WsusOutput.Text=(deliveryReports.TryGetValue(ExecutionRow(r,true).JobId+r.Host,out var delivery)&&!ChannelOutput(r,true).Contains(delivery)?delivery+"\n\n":"")+ChannelOutput(r,true);WsusServerOutput.Text=serverReports.TryGetValue(r.Host,out var report)?report:"Отчёт выбранного компьютера можно прочитать кнопкой «Прочитать отчёт сервера».";Notify(r.Name+": "+r.Status);UpdateWsusStage();PaintReport(r.Host);}else{OutputBox.Text="Выберите компьютер или задание в истории.";WsusOutput.Text="Выберите компьютер.";Notify("Компьютер не выбран.");}}
 void OpenJob(RemoteJob job,bool showResults){historyViewId=job.Id;loadingRows=true;try{foreach(var t in job.Targets)if(!Computers.Any(r=>r.Host.Equals(t.Host,StringComparison.OrdinalIgnoreCase)))Computers.Add(new(t,job.Id));if(job.Targets.Count>0)ComputerGrid.SelectedItem=Computers.First(r=>r.Host.Equals(job.Targets[0].Host,StringComparison.OrdinalIgnoreCase));}finally{loadingRows=false;}ShowCurrent();RefreshOutcomes();if(showResults)MainTabs.SelectedItem=IsWsusJob(job)?WsusTab:CommandsTab;}
