 readonly Dictionary<string,TreeViewItem> computerNodes=new(StringComparer.OrdinalIgnoreCase);
 TreeViewItem BranchItem(string dn,string name){var members=Computers.Where(r=>dn==""||r.OU.Equals(dn,StringComparison.OrdinalIgnoreCase)||r.OU.EndsWith(","+dn,StringComparison.OrdinalIgnoreCase)).ToList();var model=new OuBranchState(dn,name,members);branches[dn]=model;var header=new Grid{MinWidth=145,DataContext=model};var bar=new ProgressBar{Height=24,Opacity=0.22,BorderThickness=new(0),Foreground=System.Windows.Media.Brushes.SteelBlue,Background=System.Windows.Media.Brushes.Transparent};bar.SetBinding(ProgressBar.IsIndeterminateProperty,new Binding("Busy"));header.Children.Add(bar);var text=new StackPanel{Orientation=Orientation.Horizontal};text.Children.Add(new TextBlock{Text=name,Foreground=System.Windows.Media.Brushes.White});var activity=new TextBlock{Foreground=System.Windows.Media.Brushes.LightSkyBlue};activity.SetBinding(TextBlock.TextProperty,new Binding("Activity"));text.Children.Add(activity);var check=new CheckBox{Content=text,IsThreeState=true,Margin=new(3,3,3,3)};check.SetBinding(CheckBox.IsCheckedProperty,new Binding("Selected"){Mode=BindingMode.OneWay});check.Click+=(sender,args)=>SelectBranch(model);var branchLine=new StackPanel{Orientation=Orientation.Horizontal};check.Content=null;branchLine.Children.Add(check);branchLine.Children.Add(text);header.Children.Add(branchLine);var item=new TreeViewItem{Header=header,Tag=model};item.SetBinding(ToolTipProperty,new Binding("Tooltip"){Source=model});return item;}
 void SelectBranch(OuBranchState branch){bool select=branch.Selected!=true;batchSelecting=true;try{foreach(var row in branch.Members)row.Selected=select;}finally{batchSelecting=false;}UpdateSelectionCount();}
 void RefreshBranches(){var active=History.SelectMany(j=>j.Targets.Select(t=>(Job:j,Target:t))).GroupBy(x=>x.Target.Host.ToUpperInvariant()+"|"+IsWsusJob(x.Job)).Select(g=>g.First()).Where(x=>(x.Target.Status is "Queued" or "Sending" or "Submitted" or "Running")||(x.Target.State?.DiagnosticStatus is "Pending" or "Running" or "LegacyRunning")).Select(x=>x.Target.Host).ToHashSet(StringComparer.OrdinalIgnoreCase);foreach(var branch in branches.Values)branch.Refresh(active);}
