 void SelectVisible_Click(object s,RoutedEventArgs e){foreach(var r in Computers.Where(r=>(r.Name+" "+r.OS).Contains(SearchBox.Text,StringComparison.OrdinalIgnoreCase)&&(ou==""||r.OU.Equals(ou,StringComparison.OrdinalIgnoreCase)||r.OU.EndsWith(","+ou,StringComparison.OrdinalIgnoreCase))))r.Selected=true;UpdateSelectionCount();}
 void ClearSelection_Click(object s,RoutedEventArgs e){foreach(var r in Computers)r.Selected=false;UpdateSelectionCount();}
 CommandStep FromEditor(string? code=null)=>new(){Name=CommandTitle(code??Editor.Text),Kind=((ComboBoxItem)KindBox.SelectedItem).Content.ToString()!,Code=code??Editor.Text};
 void AddStep_Click(object s,RoutedEventArgs e)=>Guard(()=>{if(string.IsNullOrWhiteSpace(Editor.Text))throw new Exception("Введите команду.");Steps.Add(FromEditor());});
 void AddSelection_Click(object s,RoutedEventArgs e)=>Guard(()=>{if(string.IsNullOrWhiteSpace(Editor.SelectedText))throw new Exception("Выделите фрагмент.");Steps.Add(FromEditor(Editor.SelectedText));});
 void EditStep_Click(object s,RoutedEventArgs e)=>Guard(()=>{int i=StepList.SelectedIndex;if(i<0)throw new Exception("Выберите шаг.");if(Steps[i].Kind is "Updates" or "UpdateScan" or "Diagnostics")throw new Exception("Встроенный шаг не является текстовой командой.");Steps[i]=FromEditor();});
 void Step_Changed(object s,SelectionChangedEventArgs e){if(StepList.SelectedItem is CommandStep t){Editor.Text=t.Code;KindBox.SelectedIndex=t.Kind=="PowerShell"?1:0;}}
 void RemoveStep_Click(object s,RoutedEventArgs e){if(StepList.SelectedItem is CommandStep t)Steps.Remove(t);}
 void Up_Click(object s,RoutedEventArgs e){int i=StepList.SelectedIndex;if(i>0){Steps.Move(i,i-1);StepList.SelectedIndex=i-1;}}
 void Down_Click(object s,RoutedEventArgs e){int i=StepList.SelectedIndex;if(i>=0&&i<Steps.Count-1){Steps.Move(i,i+1);StepList.SelectedIndex=i+1;}}
 string? Prompt(string title,string initial=""){var text=new TextBox{Text=initial,MinWidth=380,Margin=new(16)};var button=new Button{Content="Применить",ToolTip="Применить введённое значение и вернуться к заданию.",Margin=new(16),IsDefault=true};var panel=new StackPanel();panel.Children.Add(text);panel.Children.Add(button);var w=new Window{Owner=this,Title=title,Content=panel,SizeToContent=SizeToContent.WidthAndHeight,WindowStartupLocation=WindowStartupLocation.CenterOwner,ResizeMode=ResizeMode.NoResize};button.Click+=(s,e)=>w.DialogResult=true;return w.ShowDialog()==true?text.Text:null;}
 void ImportText_Click(object s,RoutedEventArgs e)=>Guard(()=>{var d=new OpenFileDialog{Filter="Команды|*.txt;*.cmd;*.bat;*.ps1|Все файлы|*.*"};if(d.ShowDialog(this)!=true)return;Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);using var reader=new StreamReader(d.FileName,Encoding.GetEncoding(System.Globalization.CultureInfo.CurrentCulture.TextInfo.ANSICodePage),true);Editor.Text=reader.ReadToEnd();KindBox.SelectedIndex=Path.GetExtension(d.FileName)==".ps1"?1:0;Notify("Выделите команды и нажмите «Добавить выделенное».");});
 void SaveLibrary_Click(object s,RoutedEventArgs e)=>Guard(()=>{if(Steps.Count==0)throw new Exception("Последовательность пуста.");var name=Prompt("Название",Steps.Count>0?Steps[0].Name:"Набор команд");if(string.IsNullOrWhiteSpace(name))return;Library.Add(new(){Name=name,Category=Prompt("Категория","Мои команды")??"Мои команды",Description=Prompt("Описание")??"",MicrosoftSource=MicrosoftBox.IsChecked==true,Steps=Store.Clone(Steps.ToList())});Save();});
 void ImportLibrary_Click(object s,RoutedEventArgs e)=>Guard(()=>{var d=new OpenFileDialog{Filter="JSON|*.json"};if(d.ShowDialog(this)!=true)return;var list=JsonSerializer.Deserialize<List<LibraryEntry>>(File.ReadAllText(d.FileName),Store.Options)??throw new Exception("Пустая библиотека.");if(list.Any(t=>t.Steps.Count==0||t.Steps.Any(x=>x.Kind is not ("CMD" or "PowerShell" or "Updates" or "UpdateScan" or "Diagnostics"))))throw new Exception("Неверный формат библиотеки.");foreach(var t in list)Library.Add(t);Save();});
 void ExportLibrary_Click(object s,RoutedEventArgs e)=>Guard(()=>{var d=new SaveFileDialog{Filter="JSON|*.json",FileName="commands.json"};if(d.ShowDialog(this)==true)File.WriteAllText(d.FileName,JsonSerializer.Serialize(Library,Store.Options));});
 async void Run_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{if(Steps.Count==0)throw new Exception("Последовательность пуста. Добавьте шаг или нажмите «Выполнить команду из редактора».");await Submit(Steps.ToList());});
 async Task Submit(List<CommandStep> source,string channel="Commands"){SuggestionsPopup.IsOpen=false;if(source.Count==0)throw new Exception("Добавьте команды.");var marked=Selected();var focused=ComputerGrid.SelectedItem as ComputerRow;if(focused==null&&marked.Count==0)throw new Exception("Выберите компьютер или отметьте цели.");if(!int.TryParse(LimitBox.Text,out limit)||limit<0)throw new Exception("Лимит: целое число от 0.");if(MicrosoftBox.IsChecked==true&&source.Any(x=>x.Kind is "Updates" or "UpdateScan"))throw new Exception("Разделите восстановление Microsoft и обновления WSUS.");var steps=Store.Clone(source);
  foreach(var name in Regex.Matches(string.Join("\n",steps.Select(x=>x.Code)),@"\{\{([A-Za-z][A-Za-z0-9_]*)\}\}").Select(m=>m.Groups[1].Value).Distinct()){var value=Prompt("Параметр "+name);if(value==null)return;foreach(var t in steps)t.Code=t.Code.Replace("{{"+name+"}}",value);}
  var preview="Источник восстановления Microsoft: "+(MicrosoftBox.IsChecked==true?"временное переключение включено; Kerio этим не разблокируется":"текущие политики клиента")+"\nАвтоперезагрузка: "+(RebootBox.IsChecked==true?"включена":"выключена")+"\n\n"+string.Join("\n\n",steps.Select(t=>t.Name+" ["+t.Kind+"]\n"+(t.Kind=="ReportRecovery"?"Очистка только кэша отчётности. Параметр сохранения копии выбирается галочкой выше. Затем выполняются поиск и запрос отчёта.":t.Code)));var confirmation=new TargetConfirmation(this,focused,marked,preview,steps.Any(t=>t.Kind=="ReportRecovery"));if(confirmation.ShowDialog()!=true)return;var selected=confirmation.Result!;bool queueAfter=false;bool exclusive=Maintenance(steps,MicrosoftBox.IsChecked==true);bool activeWsus=await HasLiveWsus(selected);if(activeWsus&&channel=="Commands"){var choice=MessageBox.Show(this,exclusive?"Команда обслуживания будет ждать завершения WSUS. Поставить в очередь?":"На цели выполняется WSUS. Да — выполнить параллельно; Нет — дождаться WSUS; Отмена — не запускать. Произвольный скрипт может мешать обновлениям.","Очередь выполнения",exclusive?MessageBoxButton.OKCancel:MessageBoxButton.YesNoCancel);if(choice==MessageBoxResult.Cancel)return;queueAfter=exclusive||choice==MessageBoxResult.No;}foreach(var step in steps.Where(t=>t.Kind=="ReportRecovery"))step.Code="$keepBackup="+(confirmation.KeepReportBackup?"$true":"$false")+";"+DeliveryScripts.Recovery;

  historyViewId="";var job=new RemoteJob{OutputChannel=channel,ExclusiveMaintenance=exclusive,QueueAfterWsus=queueAfter,StallMinutes=Store.Read("stall-minutes.json",10),Name=steps[0].Name,Steps=steps,MicrosoftSource=MicrosoftBox.IsChecked==true,AutoReboot=RebootBox.IsChecked==true,ContinueOnError=!steps.Any(t=>t.Kind=="ReportRecovery")&&ContinueBox.IsChecked==true,DiagnosticLookbackMinutes=ReadDiagnosticMinutes()};foreach(var r in selected){var t=Store.Clone(r.Target);t.Status="Queued";t.State=null;t.Output="";job.Targets.Add(t);r.JobId=job.Id;confirmedJobs.Add(job.Id+r.Host);if(preflightErrors.TryGetValue(r.Host,out var connectionError)){t.Status="ConnectionFailed";t.Output="Нет связи / проверка доступа не выполнена. Команда не отправлена.\n"+connectionError;}else if(channel=="WSUS"&&steps.Any(x=>x.Kind is "Updates" or "UpdateScan" or "CacheCleanup" or "ReportRecovery")&&backgroundUpdates.TryGetValue(r.Host,out var activity)&&(activity.Busy||activity.Jobs.Count>0||activity.Limitation.Length>0)){t.Status="InterventionRequired";t.State=new(){Status="InterventionRequired",Ended=DateTime.UtcNow.ToString("o"),Error="Запуск отложен: активное обновление либо неполная проверка активности. Повторите вручную после проверки."};t.Output=t.State.Error+"\n"+BackgroundText(r.Host,activity);}else queue.Enqueue((job,t));}History.Insert(0,job);foreach(var r in selected)RememberComputer(r.Host);if(channel=="WSUS"){foreach(var r in selected){liveReports.Remove(r.Host);if(reportCache.TryGetValue(r.Host,out var cached)){cached.Started=job.Created;serverReports[r.Host]=CachedReportText(cached);reportSeverity[r.Host]=cached.Report.Severity(job.Created);}}Store.Write("wsus-report-cache.json",reportCache);}Save();Sync(job);if(confirmation.BatchChosen)ClearSelection_Click(this,new RoutedEventArgs());ComputerGrid.SelectedItem=selected[0];MainTabs.SelectedItem=channel=="WSUS"?WsusTab:CommandsTab;ShowCurrent();SuggestionsPopup.IsOpen=false;await SendQueue();
 }
 void Sync(RemoteJob job){job.RefreshSummary();foreach(var row in Computers.Where(r=>r.JobId==job.Id)){var t=job.Targets.FirstOrDefault(t=>t.Host==row.Host);if(t==null)continue;row.Target.Status=t.Status;row.Target.State=t.State;row.Target.Output=t.Output;row.Refresh();}RefreshBranches();RefreshOutcomes();}
 async Task SendQueue(){if(sending||closing)return;sending=true;try{while(queue.Count>0&&!closing){int active=History.SelectMany(j=>j.Targets).Count(t=>t.Status is "Sending" or "Submitted" or "Running");if(limit>0&&active>=limit)break;var next=queue.Dequeue();next.Target.Status="Sending";Sync(next.Job);Save();_=SendOne(next.Job,next.Target);await Task.Delay(80);}}finally{sending=false;}}
 async Task SendOne(RemoteJob job,TargetRecord target){try{await remote.Deploy(target,job);confirmedJobs.Add(job.Id+target.Host);target.Status="Submitted";target.Output="Задание передано на "+target.Host+". Ожидание результата…";}catch(Exception ex){target.Status=ex.Message.Contains("Отказано в доступе",StringComparison.OrdinalIgnoreCase)||ex.Message.Contains("Access is denied",StringComparison.OrdinalIgnoreCase)?"AccessDenied":"ConnectionFailed";target.Output="Не удалось передать задание на "+target.Host+". Выполнение команды не подтверждено.\n\n"+ex.Message+"\n\nУчётная запись приложения: "+Environment.UserDomainName+"\\"+Environment.UserName+"\nИспользуйте «Проверить подключение» для отдельной проверки WinRM.";Notify(target.Host+": ошибка подключения. Подробности в результате компьютера.");}finally{Sync(job);if(ComputerGrid.SelectedItem is ComputerRow r&&r.JobId==job.Id&&r.Host==target.Host){ShowCurrent();}Save();if(job.Targets.All(t=>t.Status is not ("Queued" or "Sending")))Notify("Запуск: передано "+job.Targets.Count(t=>t.Status is "Submitted" or "Running")+"; недоступно "+job.Targets.Count(t=>t.Status is "ConnectionFailed" or "AccessDenied")+"; отложено "+job.Targets.Count(t=>t.Status=="InterventionRequired")+". Подробности — у каждого компьютера.");await SendQueue();}}
 static string UpdateSummary(IEnumerable<UpdateOutcome> updates)=>string.Join("\n",updates.Where(u=>!string.IsNullOrWhiteSpace(u.Title)).Select(u=>u.Title+" · "+(u.Download.HasValue?"скачивание: ":u.ResultCode.HasValue?"установка: ":"поиск: ")+((u.Download??u.ResultCode) switch{2=>"успешно",3=>"с замечаниями",4=>"ошибка",5=>"отменено",0=>"не начато",1=>"выполняется",_=>"найдено"})+(u.HResult.HasValue&&u.HResult!=0?" · HRESULT "+ExecutionDiagnosis.Code(u.HResult.Value)+" · "+ExecutionDiagnosis.Explain(u.HResult.Value):"")+(u.RebootRequired?" · нужна перезагрузка":"")));
 static string Timeline(string runner,IEnumerable<UpdateOutcome> updates){var rows=new List<string>();foreach(Match entry in Regex.Matches(runner,@"(?m)^([^\r\n]+?) Этап завершён: (.+); секунд: (\d+)")){string name=entry.Groups[2].Value;if(name is "WSUS · проверка и запрос отчёта" or "WSUS · установка и запрос отчёта")continue;var update=updates.FirstOrDefault(u=>name.EndsWith(u.Title)&&u.Title.Length>0);var code=name.StartsWith("Скачивание")?update?.Download:name.StartsWith("Установка")?update?.ResultCode:null;string result=code switch{2=>"успешно",3=>"с замечаниями",4=>"ошибка",5=>"отменено",_=>"завершено"};rows.Add(name+" · "+entry.Groups[3].Value+" сек · "+result);}var search=Regex.Match(runner,@"Поиск завершён\. Применимых обновлений: (\d+)");if(search.Success)rows.Add("Применимых обновлений по текущим политикам: "+search.Groups[1].Value);if(runner.Contains("Запросы завершены:"))rows.Add("Запрос отправки отчёта: команды клиента завершены; получение см. в данных сервера.");return string.Join("\n",rows);}
 static string PresentResult(string host,PollResult data){var state=data.State!;var sections=new List<string>{"## Итог задания\nКомпьютер: "+host+"\nСостояние: "+ComputerRow.StatusText(state.Status)+"\nНачало: "+LocalDateConverter.Format(state.Started)+"\nЗавершение: "+LocalDateConverter.Format(state.Ended)+(state.Error.Length>0?"\nОшибка: "+state.Error:"")};
  if(DateTimeOffset.TryParse(state.Started,out var executionStart)&&DateTimeOffset.TryParse(state.Ended,out var executionEnd)&&executionEnd>=executionStart){var duration=executionEnd-executionStart;sections[0]+="\nВыполнение на клиенте: "+(int)duration.TotalMinutes+" мин "+duration.Seconds+" сек";}
  var files=Regex.Split(data.Output,@"(?m)^--- (.+?) ---\r?$");string runner="",technical="",diagnostic="",commandOutput="";for(int i=1;i+1<files.Length;i+=2){var name=files[i];var body=files[i+1].Trim();if(name.EndsWith(".err"))body=PowerShellBridge.PlainError(body);if(body.Length==0)continue;if(name=="runner.log")runner=body;else if(name.Contains("diagnostics."))diagnostic+="--- "+name+" ---\n"+PowerShellBridge.PlainError(body)+"\n";else if(name.EndsWith(".out")&&!name.Contains("report"))commandOutput+=body+"\n";else if(!name.EndsWith("updates.json"))technical+="--- "+name+" ---\n"+body+"\n";}
  if(state.ActivityMessage.Length>0||state.Recommendation.Length>0)sections.Add("## Контроль выполнения и рекомендации\n"+state.TransferText+"\n"+state.ActivityMessage+"\n"+state.Recommendation+(string.IsNullOrEmpty(state.Ended)&&state.RecommendationAction is "Download" or "Queue" or "Defender"?"\nДействие доступно после завершения задания. Текущее обновление продолжает выполняться.":""));if(state.Results.Count>0)sections.Add("## Результаты команд\n"+string.Join("\n",state.Results.Select(t=>t.Name+": "+(state.Status=="Cancelled"&&ReferenceEquals(t,state.Results.LastOrDefault())?"остановлено":t.ExitCode==0?(t.NativeExitCode.GetValueOrDefault()!=0?"PowerShell завершён; предупреждение: проверьте код внешней программы":"успешно"):"ошибка")+" · "+ExecutionDiagnosis.Code(t.ExitCode)+(t.NativeExitCode.HasValue?"; внешняя программа: "+ExecutionDiagnosis.Code(t.NativeExitCode.Value):""))));if(runner.Length>0)sections.Add("## Этапы выполнения\n"+Timeline(runner,data.Updates));var updates=UpdateSummary(data.Updates);if(data.Updates.Count>0)sections[0]+="\nУстановлено: "+data.Updates.Count(u=>u.ResultCode==2)+"; ошибок: "+data.Updates.Count(u=>u.Download==4||u.ResultCode==4)+"; отменено: "+data.Updates.Count(u=>u.Download==5||u.ResultCode==5);if(updates.Length>0)sections.Add("## Результаты обновлений\n"+updates);else if(runner.Contains("Применимых обновлений: 0"))sections.Add("## Результаты обновлений\nПрименимых обновлений по текущим политикам нет.");
  if(data.Output.Contains("No Format Information")||data.Output.Contains("WARNING:"))sections.Insert(1,"## Полнота диагностики · предупреждение\nСбор завершён, но часть диагностических данных отсутствует или не расшифрована. Это ограничение диагностики, а не доказательство сбоя клиента. Исходные файлы доступны в полном журнале.");if(commandOutput.Length>0)sections.Add("## Вывод команды\n"+LogPresentation.Compact(commandOutput));var knownCodes=Regex.Matches(technical,@"(?i)(?:0x|\[)(8[0-9a-f]{7})").Cast<Match>().Select(m=>Convert.ToUInt32(m.Groups[1].Value,16)).Distinct().Take(12).ToList();if(knownCodes.Count>0)sections.Add("## Расшифровка кодов · технический контекст\nКоды из системного журнала не обязательно относятся к текущему сбою; учитывайте этап и время.\n"+string.Join("\n",knownCodes.Select(c=>"0x"+c.ToString("X8")+": "+ExecutionDiagnosis.Explain(unchecked((int)c)))));string context=LogPresentation.ErrorContext(technical);if(!context.StartsWith("В выбранном интервале"))sections.Add("## Ошибки и предупреждения · технический контекст\n"+context+"\nСовпадение по времени не доказывает причину сбоя; ошибки повторных попыток могут завершиться успехом.");if(technical.Length>0)sections.Add("## Технический журнал\n"+LogPresentation.Compact(runner+"\n"+technical));if(state.DiagnosticStatus=="NotRequested"&&diagnostic.Length>0)sections.Add("## Диагностика долгой операции\n"+LogPresentation.Compact(diagnostic));if(state.DiagnosticStatus!="NotRequested")sections.Add("## Сбор диагностики\n"+DiagnosticLabel(state)+(state.DiagnosticError.Length>0?"\n"+state.DiagnosticError:"")+"\n"+diagnostic);return LogPresentation.LocalTimes(string.Join("\n\n",sections));}
 static void Reconcile(PollResult data){var state=data.State;if(state==null)return;if(state.Status is "Failed" or "CompletedWithErrors" or "Completed" or "Cancelled" or "InterventionRequired"){if(string.IsNullOrEmpty(state.StageEnded))state.StageEnded=state.Results.LastOrDefault(r=>!string.IsNullOrEmpty(r.Ended))?.Ended??state.Ended;if(string.IsNullOrEmpty(state.Ended)&&data.AgentAlive&&data.TaskState=="Running"&&state.DiagnosticStatus=="NotRequested")state.DiagnosticStatus="LegacyRunning";else if(state.DiagnosticStatus=="LegacyRunning"&&!data.AgentAlive){state.DiagnosticStatus="Failed";state.DiagnosticError="Старый исполнитель завершён. Итог сбора диагностики неизвестен.";}}if((state.DiagnosticStatus is "Pending" or "Running")&&!data.AgentAlive&&(data.TaskState is "Ready" or "Disabled" or "Missing")&&DateTimeOffset.TryParse(state.Updated,out var diagnosticUpdated)&&DateTimeOffset.UtcNow-diagnosticUpdated>TimeSpan.FromMinutes(2)){state.DiagnosticStatus="Failed";state.DiagnosticError="Исполнитель завершился без конечного результата диагностики. Основной результат сохранён.";}var failed=state.Results.LastOrDefault(r=>r.ExitCode!=0);if(failed!=null&&string.IsNullOrWhiteSpace(state.Error))state.Error="Код завершения: "+ExecutionDiagnosis.Code(failed.ExitCode)+". "+ExecutionDiagnosis.Explain(failed.ExitCode);if(state.Status=="Running"&&!string.IsNullOrWhiteSpace(state.Ended))state.Status=failed==null?"Completed":"Failed";if((state.Status is "Running" or "Queued")&&DateTimeOffset.TryParse(state.Updated,out var at)&&DateTimeOffset.UtcNow-at>TimeSpan.FromMinutes(2)&&!data.AgentAlive&&(data.TaskState is "Ready" or "Disabled" or "Missing")){state.Status="InterventionRequired";state.Error="Исполнитель больше не работает, но конечное состояние задания не сохранено. Планировщик: "+data.TaskState+", код задачи: "+data.TaskResult+" (0x"+unchecked((uint)data.TaskResult).ToString("X8")+"). Код задачи не является кодом DISM/SFC. Проверьте журналы; команда автоматически не перезапускается.";}}
 static bool ShouldCollectServicing(RemoteJob? job)=>job!=null&&(IsWsusJob(job)||job.Steps.Any(s=>Regex.IsMatch(s.Code,@"(?i)\b(sfc|dism|chkdsk|Repair-WindowsImage)\b")));
 async Task Poll(ComputerRow row){
  var id=row.JobId;var host=row.Host;var key=id+host;if(id==""||!polling.Add(key))return;
  var readClock=System.Diagnostics.Stopwatch.StartNew();try{var data=await remote.Poll(row.Target,id);if(data.State!=null){
   Reconcile(data);
   confirmedJobs.Add(key);var output=await Task.Run(()=>PresentResult(host,data));

   foreach(var job in History.Where(j=>j.Id==id)){var t=job.Targets.FirstOrDefault(t=>t.Host==host);if(t!=null){t.Status=data.State.Status;t.State=data.State;t.Output=output;}Sync(job);RememberSuccessful(job);}
   if(row.JobId==id){row.Target.State=data.State;row.Target.Status=data.State.Status;row.Target.Output=output;row.Refresh();if(IsCurrent(row)){ShowCurrent();Notify(row.Name+": "+row.Status+" · получение и подготовка результата: "+readClock.Elapsed.TotalSeconds.ToString("F1")+" сек");}RefreshOutcomes();}Save();
   if((data.State.Status is "Completed" or "AwaitingReboot" or "RebootScheduled" or "Failed" or "CompletedWithErrors") && History.Any(j=>j.Id==id&&j.Steps.Any(t=>t.Kind is "UpdateScan" or "Updates")) && wsusChecked.Add(key) && !string.IsNullOrWhiteSpace(WsusHost.Text)){reportWaiting[host]=(id,DateTimeOffset.UtcNow.AddMinutes(2),DateTimeOffset.UtcNow);await FetchWsusReport(row);}
   if(data.State.Status is "Completed" or "CompletedWithErrors" or "Failed" or "Cancelled" or "VerifiedAfterReboot"){
    if(data.Client!=null&&History.Any(j=>j.Id==id&&j.Steps.Any(t=>t.Kind=="DeliveryDiagnostics"))&&wsusChecked.Add(key+"delivery")){try{var settings=ReadWsus();var evidence=await remote.DeliveryServer(settings,data.Client,data.State.Started,History.First(j=>j.Id==id).DiagnosticLookbackMinutes);var text=DeliveryPresentation.Format(data.Client,evidence,DateTimeOffset.UtcNow);deliveryReports[key]=text;Store.Write("delivery-reports.json",deliveryReports);var path=Path.Combine(Store.Root,"Diagnostics",row.Name+"_"+id+"_delivery.json");Directory.CreateDirectory(Path.GetDirectoryName(path)!);var json=JsonSerializer.Serialize(new{Client=data.Client,Server=evidence},Store.Options);File.WriteAllText(path,json);var archive=Path.Combine(Store.Root,"Logs",row.Host+"_"+id);Directory.CreateDirectory(archive);File.WriteAllText(Path.Combine(archive,"delivery-server.json"),json);if(IsCurrent(row))ShowCurrent();}catch(Exception ex){deliveryReports[key]="## Диагностика доставки отчёта\nСерверные данные не получены: "+ex.Message;if(IsCurrent(row))ShowCurrent();}}
    if(data.State.DiagnosticStatus is not ("Pending" or "Running" or "LegacyRunning")&&data.State.RestoreStatus is not ("Pending" or "InterventionRequired")&&!archivedJobs.Contains(key)){try{await remote.Logs(row.Target,id,true);archivedJobs.Add(key);Store.Write("archived-jobs.json",archivedJobs.ToList());}catch(Exception ex){if(IsCurrent(row))Notify("Результат сохранён в истории; полный архив пока получить не удалось: "+ex.Message);}}
   }
   if((data.State.Status is "Failed" or "CompletedWithErrors" or "InterventionRequired")&&ShouldCollectServicing(History.FirstOrDefault(j=>j.Id==id))){if(wsusChecked.Add(key+"diagnostic")){try{var diagnostic=await remote.ServicingDiagnostics(row.Target,id,ReadDiagnosticMinutes());var folder=Path.Combine(Store.Root,"Diagnostics");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,row.Name+"_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".txt"),diagnostic,new UTF8Encoding(true));servicingReports[id+host]="## Первичная диагностика выбранного задания\n"+LogPresentation.LocalTimes(LogPresentation.Compact(diagnostic));if(IsCurrent(row))ShowCurrent();}catch(Exception ex){if(IsCurrent(row))Notify("Задание остановлено; диагностику получить не удалось: "+ex.Message);}}}
  }else if(IsCurrent(row)){Notify(row.Name+": результат ещё не появился на целевом компьютере; сохранённый вывод оставлен.");}}catch(Exception ex){if(IsCurrent(row))Notify(row.Name+": не удалось обновить результат; сохранённый вывод оставлен. "+ex.Message);}finally{polling.Remove(key);}
 }
