 void SaveWsus_Click(object s,RoutedEventArgs e)=>Guard(()=>{Store.Write("wsus-settings.json",ReadWsus());UpdateWsusHeader();Notify("Настройки WSUS сохранены.");});
 void RevealCurrent(){if(ComputerGrid.SelectedItem is ComputerRow r&&computerNodes.TryGetValue(r.Host,out var leaf)){for(var parent=ItemsControl.ItemsControlFromItemContainer(leaf) as TreeViewItem;parent!=null;parent=ItemsControl.ItemsControlFromItemContainer(parent) as TreeViewItem)parent.IsExpanded=true;leaf.IsSelected=true;leaf.BringIntoView();}}
 static string DiagnosticLabel(RemoteState state){var label=state.DiagnosticStatus switch{"Pending"=>"ожидает сбора","Running"=>"собирается · лимит 5 минут","LegacyRunning"=>"старый исполнитель ещё работает; ограничение новой версии к нему не применяется","Completed"=>"собрана","TimedOut"=>"остановлена по лимиту/запросу; доступны частичные журналы","Failed"=>"не завершена",_=>"не запрошена"};if(state.DiagnosticStatus=="Running"&&DateTimeOffset.TryParse(state.DiagnosticStarted,out var start))label+=" · "+(int)(DateTimeOffset.UtcNow-start).TotalSeconds+" сек";return label+(state.DiagnosticError==""?"":" · "+state.DiagnosticError);}
 void UpdateWsusStage(){if(ComputerGrid.SelectedItem is not ComputerRow selected){WsusStage.Text="Выберите компьютер для просмотра этапа.";return;}var r=ExecutionRow(selected,MainTabs.SelectedItem==WsusTab);var state=r.Target.State;RecommendationButton.Visibility=state!=null&&state.Recommendation.Length>0?Visibility.Visible:Visibility.Collapsed;RecommendationButton.ToolTip=state?.Recommendation;RecommendationButton.IsEnabled=state!=null&&(!string.IsNullOrEmpty(state.Ended)||state.RecommendationAction is not ("Download" or "Queue" or "Defender"));string duration=state==null?"":LogPresentation.Duration(state,DateTimeOffset.UtcNow);string elapsed=duration==""?"":" · этап: "+duration;if(state!=null&&r.Target.Status=="Running"){if(state.Progress.HasValue)elapsed+=" · "+(state.ProgressValue!=""?state.ProgressValue:state.Progress.ToString())+"%";if(DateTimeOffset.TryParse(state.LastOutputUtc,out var outputAt))elapsed+=" · новый вывод: "+(int)(DateTimeOffset.UtcNow-outputAt).TotalMinutes+" мин назад";if(DateTimeOffset.TryParse(state.LastProgressUtc,out var progressAt))elapsed+=" · изменение процента: "+(int)(DateTimeOffset.UtcNow-progressAt).TotalMinutes+" мин назад";if(DateTimeOffset.TryParse(state.Updated,out var heartbeat)&&DateTimeOffset.UtcNow-heartbeat>TimeSpan.FromSeconds(90))elapsed+=" · состояние агента давно не обновлялось";}WsusStage.Text=r.Name+" · "+r.Status+" · "+r.Stage+elapsed;WsusProgress.IsIndeterminate=r.Busy;WsusProgress.Value=r.Progress;CurrentComputer.Text=r.Name;CurrentDetails.Text=r.OS+" · "+r.Host;CurrentStage.Text=r.Status+" · "+r.Stage+elapsed+(state!=null&&!string.IsNullOrWhiteSpace(state.Error)?(string.IsNullOrEmpty(state.Ended)?" · Ошибка предыдущего обновления; см. журнал":" · "+state.Error):"");CurrentStage.Foreground=r.Target.Status is "Failed" or "CompletedWithErrors" or "InterventionRequired"?System.Windows.Media.Brushes.Firebrick:System.Windows.Media.Brushes.Black;CurrentProgress.IsIndeterminate=r.Busy;CurrentProgress.Value=r.Progress;CurrentProgress.Foreground=r.Target.Status is "Failed" or "CompletedWithErrors" or "InterventionRequired"?System.Windows.Media.Brushes.Firebrick:System.Windows.Media.Brushes.SteelBlue;if(state!=null&&(r.Target.Status is "Submitted" or "Running")&&!confirmedJobs.Contains(r.JobId+r.Host))CurrentStage.Text+=" · сохранённое состояние; требуется проверка";if(state!=null&&state.StopMessage.Length>0)CurrentStage.Text+=" · "+state.StopMessage;if(state!=null){CurrentStage.Text+=(state.TransferText.Length>0?" · "+state.TransferText:"")+(state.ActivityMessage.Length>0?" · "+state.ActivityMessage:"");}int activeForHost=History.SelectMany(j=>j.Targets).Count(t=>t.Host.Equals(selected.Host,StringComparison.OrdinalIgnoreCase)&&t.Status is "Queued" or "Sending" or "Submitted" or "Running");if(activeForHost>1)CurrentDetails.Text+=" · активных заданий: "+activeForHost;if(backgroundUpdates.TryGetValue(selected.Host,out var background)){var text=BackgroundText(selected.Host,background);if(text.Length>0)CurrentStage.Text+="\n"+text;var download=background.Downloads.FirstOrDefault(d=>d.State=="Transferring");if(download!=null&&!r.Busy){CurrentProgress.IsIndeterminate=download.Total<=0||download.Received>download.Total;CurrentProgress.Value=download.Total>0?Math.Clamp((double)download.Received*100/download.Total,0,100):0;}}CurrentStage.ToolTip=CurrentStage.Text;DiagnosticStage.Text=state==null?"":"Диагностика: "+DiagnosticLabel(state);DiagnosticStage.Visibility=state!=null&&state.DiagnosticStatus!="NotRequested"?Visibility.Visible:Visibility.Collapsed;}
 int ReadDiagnosticMinutes(){if(!int.TryParse(DiagnosticMinutes.Text,out var minutes)||minutes<0||minutes>1440)throw new Exception("Интервал диагностики: от 0 до 1440 минут перед заданием.");return minutes;}
 void SaveDiagnosticSettings_Click(object s,RoutedEventArgs e)=>Guard(()=>{Store.Write("diagnostic-settings.json",ReadDiagnosticMinutes());Notify("Интервал диагностики сохранён.");});
 void PaintReport(string host){var severity=reportSeverity.TryGetValue(host,out var value)?value:"Unknown";WsusServerOutput.Background=severity=="Error"?new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(254,226,226)):severity=="Warning"?new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(255,247,221)):severity=="Success"?new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(230,247,237)):System.Windows.Media.Brushes.White;WsusReportTitle.Text="Данные сервера WSUS о выбранном ПК"+(reportCache.ContainsKey(host)&&!liveReports.Contains(host)?" · сохранённый снимок":"")+(severity=="Error"?" · ошибка":severity=="Warning"?" · предупреждение":severity=="Success"?" · без замечаний":"");}
 void RefreshOutcomes(){bool wsus=MainTabs.SelectedItem==WsusTab;foreach(var row in Computers){var execution=ExecutionRow(row,wsus);string result=execution.Target.Status switch{"Failed" or "CompletedWithErrors" or "AccessDenied" or "ConnectionFailed" or "InterventionRequired"=>"Error","AwaitingReboot" or "RebootScheduled" or "Cancelled"=>"Warning","Completed" or "VerifiedAfterReboot"=>"Success",_=>""};if(wsus&&result=="Success"){result=reportSeverity.TryGetValue(row.Host,out var severity)?severity:"Warning";}row.SetOutcome(result,(wsus?"WSUS":"Команды")+" · "+execution.Status+" · задание "+execution.JobId+" · "+LocalDateConverter.Format(execution.Target.State?.Ended??execution.Target.State?.Updated??""));}RefreshActivity();}

 async Task FetchWsusReport(ComputerRow row){if(!reportReading.Add(row.Host))return;try{var settings=ReadWsus();var result=await remote.Wsus(settings.Host,settings.Port,settings.Ssl,row.Host);var report=JsonSerializer.Deserialize<WsusReport>(result,Store.Options)??throw new Exception("Пустой отчёт WSUS.");var started=reportWaiting.TryGetValue(row.Host,out var pending)?History.FirstOrDefault(j=>j.Id==pending.Id)?.Targets.FirstOrDefault(t=>t.Host.Equals(row.Host,StringComparison.OrdinalIgnoreCase))?.State?.Started??"":ExecutionRow(row,true).Target.State?.Started??"";SaveReportCache(row.Host,report,settings.Host+":"+settings.Port,started);serverReports[row.Host]=report.Format(settings.Host+":"+settings.Port,started);reportSeverity[row.Host]=report.Severity(started);if(report.Fresh(started))reportWaiting.Remove(row.Host);if(IsCurrent(row)){WsusServerOutput.Text=serverReports[row.Host];PaintReport(row.Host);Notify(row.Name+": данные сервера WSUS прочитаны.");}RefreshOutcomes();await CheckOldReport(row,report);}catch(Exception ex){serverReports[row.Host]="Не удалось прочитать данные сервера WSUS: "+ex.Message;reportSeverity[row.Host]="Error";if(IsCurrent(row)){WsusServerOutput.Text=serverReports[row.Host];PaintReport(row.Host);}RefreshOutcomes();}finally{reportReading.Remove(row.Host);}}

 async Task ConfirmPendingReports(){foreach(var entry in reportWaiting.ToList()){if(DateTimeOffset.UtcNow<entry.Value.Next)continue;if(DateTimeOffset.UtcNow>=entry.Value.Until){reportWaiting.Remove(entry.Key);if(serverReports.ContainsKey(entry.Key)){serverReports[entry.Key]+="\nОжидание свежего отчёта завершено (2 минуты). Повторите чтение отчёта вручную.";if((ComputerGrid.SelectedItem as ComputerRow)?.Host.Equals(entry.Key,StringComparison.OrdinalIgnoreCase)==true)WsusServerOutput.Text=serverReports[entry.Key];}continue;}reportWaiting[entry.Key]=(entry.Value.Id,entry.Value.Until,DateTimeOffset.UtcNow.AddSeconds(15));var row=Computers.FirstOrDefault(r=>r.Host.Equals(entry.Key,StringComparison.OrdinalIgnoreCase))??History.Where(j=>j.Id==entry.Value.Id).SelectMany(j=>j.Targets).Where(t=>t.Host.Equals(entry.Key,StringComparison.OrdinalIgnoreCase)).Select(t=>new ComputerRow(t,entry.Value.Id)).FirstOrDefault();if(row!=null)await FetchWsusReport(row);}}
